#' Campionamento a due stadi
#'
#' 
#' @param data .
#' @param psu_var Variabile che identifica le unità primarie (PSU = primary
#'   sampling units): tipicamente città, scuole, quartieri. Dal primo stadio
#'   vengono estratte casualmente n_g PSU.
#' @param id_var Variabile usata per identificare le unità di secondo stadio
#'   (SSU). Se specificata, la tabella "Unità estratte" mostra gli ID dei
#'   soggetti selezionati.
#' @param tuto .
#' @param psu_mode .
#' @param ng .
#' @param fg .
#' @param ssu_mode Come allocare le unità di secondo stadio. 'fixed': estrae b
#'   unità da ciascuna PSU selezionata. 'frac': estrae una frazione f_b della
#'   numerosità di ciascuna PSU. 'all': prende tutte le unità delle PSU
#'   (equivalente al campionamento a grappoli).
#' @param b .
#' @param fb .
#' @param seed .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$instructions} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$psu_table} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$extracted} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$out_freq} \tab \tab \tab \tab \tab an output \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
samplemultistage <- function(
    data,
    psu_var,
    id_var,
    tuto = TRUE,
    psu_mode = "ng",
    ng = 3,
    fg = 0.3,
    ssu_mode = "fixed",
    b = 5,
    fb = 0.5,
    seed = 1) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("samplemultistage requires jmvcore to be installed (restart may be required)")

    if ( ! missing(psu_var)) psu_var <- jmvcore::resolveQuo(jmvcore::enquo(psu_var))
    if ( ! missing(id_var)) id_var <- jmvcore::resolveQuo(jmvcore::enquo(id_var))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(psu_var), psu_var, NULL),
            `if`( ! missing(id_var), id_var, NULL))


    options <- samplemultistageOptions$new(
        psu_var = psu_var,
        id_var = id_var,
        tuto = tuto,
        psu_mode = psu_mode,
        ng = ng,
        fg = fg,
        ssu_mode = ssu_mode,
        b = b,
        fb = fb,
        seed = seed)

    analysis <- samplemultistageClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

